import pyomo.environ as pyo

DATA = {
    "experiments": ["alpha", "beta"],
    "resources": ["metal", "acid"],
    "electricity": {"alpha": 8, "beta": 10},
    "usage": {
        ("metal", "alpha"): 3,
        ("metal", "beta"): 5,
        ("acid", "alpha"): 5,
        ("acid", "beta"): 4,
    },
    "availability": {"metal": 800, "acid": 750},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.E = pyo.Set(initialize=d["experiments"])
    model.R = pyo.Set(initialize=d["resources"])

    model.conduct = pyo.Var(model.E, within=pyo.NonNegativeIntegers)

    def obj_rule(m):
        return sum(d["electricity"][e] * m.conduct[e] for e in m.E)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def resource_rule(m, r):
        return sum(d["usage"][(r, e)] * m.conduct[e] for e in m.E) <= d["availability"][r]

    model.resource_limit = pyo.Constraint(model.R, rule=resource_rule)

    return model
